fn get_column(input: &Vec<Vec<i8>>, j: usize, _m: usize, n: usize) -> Vec<i8> {
    // Extract column j from the input matrix.
    // We assume 0 <= j < _m and input.len() == n.
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Transpose the n×m matrix into an m×n matrix.
    // For each column j in 0..m, collect input[..][j] into a new row.
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}